1	package org.springframework.samples.petclinic.rest.validation;
2	
3	/**
4	 * Normalizes free-form postal address input into a canonical stored form.
5	 *
6	 * <p>Rules:
7	 * <ul>
8	 *   <li>Leading and trailing whitespace is trimmed and internal runs of whitespace
9	 *       are collapsed to a single space.</li>
10	 *   <li>The text is upper-cased.</li>
11	 *   <li>Common street-type abbreviations are expanded token-by-token:
12	 *       {@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}.</li>
13	 * </ul>
14	 *
15	 * <p>For example {@code '  12  main  st '} becomes {@code '12 MAIN STREET'} and
16	 * {@code '7 elm ave'} becomes {@code '7 ELM AVENUE'}.
17	 */
18	public final class AddressNormalizer {
19	
20	    private AddressNormalizer() {
21	    }
22	
23	    /**
24	     * Normalizes raw address input, or returns {@code null} when the input is {@code null}.
25	     * An input that is blank (empty once whitespace is collapsed) normalizes to an empty
26	     * string, so the required-field check rejects it.
27	     *
28	     * @param raw the raw address input (may be {@code null})
29	     * @return the normalized address (e.g. {@code '12 MAIN STREET'}), or {@code null}
30	     */
31	    public static String normalize(String raw) {
32	        if (raw == null) {
33	            return null;
34	        }
35	        String collapsed = raw.trim().replaceAll("\\s+", " ").toUpperCase();
36	        if (collapsed.isEmpty()) {
37	            return collapsed;
38	        }
39	        String[] tokens = collapsed.split(" ");
40	        StringBuilder sb = new StringBuilder(collapsed.length());
41	        for (int i = 0; i < tokens.length; i++) {
42	            if (i > 0) {
43	                sb.append(' ');
44	            }
45	            sb.append(expand(tokens[i]));
46	        }
47	        return sb.toString();
48	    }
49	
50	    private static String expand(String token) {
51	        return switch (token) {
52	            case "ST" -> "STREET";
53	            case "RD" -> "ROAD";
54	            case "AVE" -> "AVENUE";
55	            default -> token;
56	        };
57	    }
58	}
