Owner toOwner(OwnerFieldsDto ownerDto);

/**
 * Resolves the owner's stored {@code address} after the field mapping runs. The structured
 * {@code addressLine1}/{@code addressLine2} fields are preferred when a non-blank
 * {@code addressLine1} is supplied: the composed address is the normalized {@code addressLine1}
 * with a single space and the normalized {@code addressLine2} appended when {@code addressLine2}
 * is present. When no structured line is supplied it falls back to the normalized flat
 * {@code address}, keeping the request backward-compatible.
 */
@org.mapstruct.AfterMapping
default void composeAddress(OwnerFieldsDto ownerDto, @org.mapstruct.MappingTarget Owner owner) {
    String line1 = AddressNormalizer.normalize(ownerDto.getAddressLine1());
    if (line1 != null && !line1.isBlank()) {
        String line2 = AddressNormalizer.normalize(ownerDto.getAddressLine2());
        owner.setAddress(line2 != null && !line2.isBlank() ? line1 + " " + line2 : line1);
    }
    else {
        owner.setAddress(AddressNormalizer.normalize(ownerDto.getAddress()));
    }
}

